                np.asarray([str(pair[1]) for pair in event_pairs], dtype=str),
            )
        )
    y_true, y_pred = pairs("onset_ms")
    errors = [
        abs(float(pred) - float(truth))
        for truth, pred in zip(y_true, y_pred)
        if truth is not None and pred is not None
    ]
    if errors:
        metrics["onset_mae_ms"] = float(np.mean(errors))
        metrics["onset_median_ae_ms"] = float(np.median(errors))
        metrics["onset_p90_ae_ms"] = float(np.quantile(errors, 0.9))
        for tolerance in (10, 25, 50):
            metrics[f"onset_within_{tolerance}ms"] = float(np.mean(np.asarray(errors) <= tolerance))
    return metrics
from robot_observability.metrics import evaluate_rows, parse_answer


def test_parse_last_answer_object() -> None:
    text = 'Evidence: stable. Answer: {"contact":false,"onset_ms":null}'
    assert parse_answer(text) == {"contact": False, "onset_ms": None}


def test_metrics_include_invalid_outputs() -> None:
    rows = [
        {"target": {"contact": True}, "output": 'Answer: {"contact":true}'},
        {"target": {"contact": False}, "output": "not json"},
    ]
    metrics = evaluate_rows(rows)
    assert metrics["parse_validity"] == 0.5
    assert metrics["contact_accuracy"] == 1.0

